exercise.solution:
fn parse_positive(input: &str) -> Result<i32, String> {
    let n = input.parse::<i32>().map_err(|e| format!("not a number: {e}"))?;
    if n <= 0 {
        return Err(format!("{n} is not positive"));
    }
    Ok(n)
}

fn main() {
    for input in ["42", "-7"] {
        println!("{input} → {:?}", parse_positive(input));
    }
}
